FILE ClientA.dfy
include "Facts.dfy"
module ClientA {
  import F = Facts`ViewA
  lemma Prove(s: seq<int>, t: seq<int>, u: seq<int>, k: nat)
    requires F.Size(s) > k
    ensures F.Large((s + t) + u, k)
  {
  }
}

FILE ClientB.dfy
include "Facts.dfy"
module ClientB {
  import F = Facts`ViewA
  lemma Prove(s: seq<int>, t: seq<int>, u: seq<int>, k: nat)
    requires F.Size(t) > k
    ensures F.Large(s + (t + u), k)
  {
  }
}

FILE Facts.dfy
module Facts {
  export ViewA provides Size, Large, ConcatA, Finish
  export ViewB provides Size, Large, ConcatB, Finish
  opaque function Size(s: seq<int>): nat { |s| }
  opaque predicate Large(s: seq<int>, k: nat) { Size(s) > k }
  lemma ConcatA(s: seq<int>, t: seq<int>)
    ensures Size(s + t) == Size(s) + Size(t)
  { reveal Size(); }
  lemma ConcatB(s: seq<int>, t: seq<int>)
    ensures Size(s + t) == Size(s) + Size(t)
  { reveal Size(); }
  lemma Finish(s: seq<int>, k: nat)
    requires Size(s) > k
    ensures Large(s, k)
  { reveal Large(); }
}
